            "text": "{\"findings\":[{\"tipo\":\"GC\",\"causa_raiz\":\"Alocação excessiva de memória gerenciada (5,4 MB no frame analisado) no método Update() devido à concatenação de strings em loop ('s += i.ToString()') e à criação contínua de arrays temporários ('new object[10000]'). No C#, strings são imutáveis; cada concatenação gera uma nova instância na memória heap, acionando o Garbage Collector (GC) e congelando a CPU por 25.84ms para limpeza, além do uso de GameObject.FindObjectsOfType() repetidas vezes por frame.\",\"codigo_refatorado\":\"using System.Text; using UnityEngine; namespace PerformanceAdvisor.StressTest { public class StressTestScene : MonoBehaviour { public bool stressGc = false; public bool stressCpu = false; public bool stressDraw = false; public GameObject testPrefab; [Range(1, 20)] public float spawnRadius = 10f; [Range(1, 50)] public int cubesPerFrame = 1; public bool useUniqueMaterials = false; [Range(1, 512)] public int cpuScansPerFrame = 1; public int emptyObjects = 0; public int gcConcatIterations = 1000; public int gcArrayAllocs = 0; public int overdrawLayers = 0; public Material overdrawMaterial; [Range(0, 2000)] public int prepopulateCount = 0; private StringBuilder _cachedStringBuilder; private MaterialPropertyBlock _propertyBlock; private static readonly int ColorPropertyId = Shader.PropertyToID(\\\"_Color\\\"); private void Awake() { _cachedStringBuilder = new StringBuilder(2048); _propertyBlock = new MaterialPropertyBlock(); } private void Start() { if (prepopulateCount \u003e 0 && testPrefab != null) { for (int i = 0; i \u003c prepopulateCount; i++) { SpawnOne(); } } for (int i = 0; i \u003c emptyObjects; i++) { new GameObject(\\\"Empty_\\\" + i); } if (overdrawLayers \u003e 0 && overdrawMaterial != null) { BuildOverdrawLayers(); } } private void BuildOverdrawLayers() { Camera cam = Camera.main; if (cam == null) return; float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad; for (int i = 0; i \u003c overdrawLayers; i++) { float d = cam.nearClipPlane + 0.05f + i * 0.001f; float h = 2f * d * Mathf.Tan(halfFov) * 1.1f; var quad = GameObject.CreatePrimitive(PrimitiveType.Quad); var col = quad.GetComponent\u003cCollider\u003e(); if (col != null) Destroy(col); quad.name = \\\"Overdraw_\\\" + i; quad.transform.SetParent(cam.transform, false); quad.transform.localPosition = new Vector3(0f, 0f, d); quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f); quad.GetComponent\u003cRenderer\u003e().sharedMaterial = overdrawMaterial; } } private void Update() { if (stressGc) { _cachedStringBuilder.Clear(); for (int i = 0; i \u003c gcConcatIterations; i++) { _cachedStringBuilder.Append(i); } } if (stressDraw && testPrefab != null) { int n = Mathf.Max(1, cubesPerFrame); for (int i = 0; i \u003c n; i++) { SpawnOne(); } } } private void SpawnOne() { var clone = Instantiate(testPrefab, Random.insideUnitSphere * spawnRadius, Quaternion.identity); if (useUniqueMaterials) { var renderer = clone.GetComponent\u003cRenderer\u003e(); if (renderer != null) { _propertyBlock.SetColor(ColorPropertyId, new Color(Random.value, Random.value, Random.value)); renderer.SetPropertyBlock(_propertyBlock); } } } } }\",\"explicacao_didatica\":\"Toda vez que você junta um texto com o operador '+' dentro de um Update, a Unity cria uma nova cópia do texto na memória (Heap). Quando essa memória enche, a Unity precisa parar o jogo inteiro momentaneamente para fazer a 'faxina' (Garbage Collection), causando os famosos engasgos (stutter/freeze). Para resolver, substituímos a concatenação contínua por StringBuilder reaproveitado e eliminamos varreduras pesadas com FindObjectsOfType. Além disso, ao mudar cores de objetos, usamos MaterialPropertyBlock em vez de 'renderer.material', evitando criar cópias duplicadas de materiais na memória da GPU.\"}],\"dicas_level_design\":null}",
